package org.example

import org.example.models.User
import tucuapi.lib.Tucuapi
import kotlin.reflect.KClass

class App {
    val greeting: String
        get() {

            return "Hello World!"
        }
}

/**
 * Modelos usados pela PoC — por enquanto, apenas o modelo `User`.
 */
private val models: Array<KClass<*>> = arrayOf(User::class)

/**
 * Monta a página HTML com o formulário gerado a partir do modelo.
 */
private fun htmlPage(model: KClass<*>): String = """
    <!DOCTYPE html>
    <html lang="pt-BR">
    <head>
        <meta charset="utf-8">
        <title>Tacuapi</title>
        <style>
            form {
              max-width: 640px;
              padding: 16px;
              border: 1px solid black;
              border-radius: 8px;

              button {
                padding: 6px 16px;
                border-radius: 7px;
                font-weight: 500;
                background: #ffbf28;
                appearance: none;
                border: none;
              }
            }
          
            div:has(input,select,textarea) {
              margin-bottom: 12px;
              display: flex;
              flex-direction: column;
              gap: 4px;

              label {
                font-weight: 600;
              }

              p {
                font-size: 0.85rem;
                margin-block: 0;
                margin-top: 4px;
              }
            }
      </style>
    </head>
    <body>
    ${Tucuapi.generateHtmlForm(model)}
    </body>
    </html>
""".trimIndent()

fun main() {
    val port = System.getenv("TACUAPI_PORT")?.toIntOrNull() ?: 8080

    // 1. Migração: cria as tabelas no PostgreSQL (roda uma única vez).
    Database.migrate(*models)

    // 2. Uma única rota: devolve o formulário HTML do modelo.
    val page = htmlPage(User::class)
    MiniHttpServer(port)
        .route("/") { Response(page) }
        .start()
}
